={{ (() => {
  const transcript = $('Armar transcripción').item.json;
  const instruction = 'Clasifica primero las imágenes. Marca paymentProof=true si alguna muestra un comprobante, soporte o recibo de pago, una transferencia bancaria o una confirmación de billetera digital. Un comprobante no es una lista de mercado y sus conceptos nunca deben convertirse en productos. Para las imágenes que sí sean listas de mercado, transcribe fielmente todo el texto legible y devuelve todos los renglones de productos en el orden visible. Conserva ortografía, cantidades, unidades, marcas, presentaciones, precios escritos y anotaciones; no normalices ni corrijas productos. Si una parte no es segura, márcala como [lectura dudosa: ...]. No inventes texto. Si hay varias imágenes, separa su contenido con IMAGEN 1, IMAGEN 2, etc. Si solo hay comprobantes, devuelve imageText vacío.';
  const content = [{ type: 'text', text: instruction }, ...transcript.imageUrls.map((url) => ({ type: 'image_url', image_url: { url, detail: 'high' } }))];
  const responseSchema = { type: 'object', additionalProperties: false, required: ['imageText', 'paymentProof'], properties: { imageText: { type: 'string' }, paymentProof: { type: 'boolean' } } };
  return JSON.stringify({ model: $('Config').item.json.OPENAI_MODEL, messages: [{ role: 'user', content }], response_format: { type: 'json_schema', json_schema: { name: 'clasificacion_imagenes', strict: true, schema: responseSchema } } });
})() }}

