={{ (() => {
  const cfg = $('Config').item.json;
  const p = $('Validar extracción').item.json.payload;
  const r = $('Resultado').item.json;
  const input = $('Normalizar entrada').item.json;
  const name = String(p.customer?.name || input.contactName || '').trim();
  const phone = String(p.customer?.phone || input.contactPhone || '').trim();
  const document = String(p.customer?.document || input.contactDocument || '').trim();
  const address = String(p.delivery?.address || p.customer?.address || input.contactAddress || '').trim();
  const neighborhood = String(p.customer?.neighborhood || input.contactNeighborhood || '').trim();
  const zone = String(p.customer?.zone || input.contactZone || '').trim();
  const pickup = p.delivery?.type === 'recogida';
  const requiredContact = Boolean(name && phone);
  const deliveryComplete = Boolean(address && neighborhood);
  const registrationComplete = requiredContact && deliveryComplete;
  const deliveryLabel = pickup ? 'Recoger en tienda' : 'Domicilio';
  const fields = [
    [cfg.CF_ULTIMO_PEDIDO_NUMERO, r.orderNumber],
    [cfg.CF_ULTIMO_PEDIDO_ESTADO, 'nuevo'],
    [cfg.CF_PEDIDO_RESUMEN, $('Validar extracción').item.json.summaryText],
    [cfg.CF_CEDULA, document],
    [cfg.CF_METODO_PAGO, p.paymentMethod],
    [cfg.CF_DIRECCION, pickup ? null : address],
    [cfg.CF_BARRIO, pickup ? null : neighborhood],
    [cfg.CF_ZONA, pickup ? null : zone],
    [cfg.CF_ENTREGA, deliveryLabel],
    [cfg.CF_REGISTRO_MINORISTA, registrationComplete ? 'Sí' : null],
  ].filter(([key, value]) => key && value !== undefined && value !== null && String(value).trim() !== '');
  const body = { customFields: fields.map(([key, value]) => ({ key, field_value: value })) };
  if (name) body.name = name;
  if (phone) body.phone = phone;
  if (!pickup && address) body.address1 = address;
  return JSON.stringify(body);
})() }}

