return $input.all().map((item, index) => {
  const response = item.json;
  const status = response.statusCode;
  const body = response.body || {};
  const ok = status >= 200 && status < 300 && Boolean(body.order_number);
  return { json: { ok, status, adjusted: ok && body.adjusted === true, mode: body.adjusted ? 'updated' : 'created',
    orderNumber: body.order_number || null, duplicate: body.duplicate === true, afterCutoff: false,
    scheduledFor: null, scheduledForLabel: null,
    error: ok ? null : (body.error || `La app respondió ${status || 'sin estado'}`) }, pairedItem: { item: index } };
});

const input = $('Normalizar entrada').first().json;
const transcript = $('Contexto de audio').first().json;
const visual = $('Contexto visual').first().json;
const conversation = $('Buscar conversación GHL').first().json;
const conversationId = conversation?.body?.conversations?.[0]?.id || null;
return $input.all().map((inputItem, itemIndex) => {
  let extracted = inputItem.json.output ?? null;
  let problem = inputItem.json.error?.message || inputItem.json.message || null;
  let ignored = false;
  if (typeof extracted === 'string') {
    try { extracted = JSON.parse(extracted); }
    catch (error) { problem = 'El modelo principal no devolvió JSON válido'; }
  }
  if (!transcript.contextOk) problem = `El endpoint de contexto no devolvió una ventana operativa válida (estado ${transcript.contextStatus || 'desconocido'})`;
  else if (transcript.readStatus !== 200) problem = `GHL respondió ${transcript.readStatus} al leer la conversación`;
  else if (!transcript.inboundMessages) { problem = 'El cliente no ha escrito nada nuevo'; ignored = true; }
  const stickerOnlyImage = /\bsticker\b/i.test(transcript.transcript || '');
  if (!problem && transcript.imageUrls.length && visual.visualProblem && !stickerOnlyImage) problem = visual.visualProblem;
  // Un comprobante de pago jamás crea, actualiza ni vuelve a cargar un pedido.
  // Se envía a Requiere ayuda para validación humana y se conserva el pedido existente sin cambios.
  if (!problem && visual.paymentProof === true) problem = 'El cliente envió un comprobante de pago para validar';
  if (!problem && !extracted) problem = 'El modelo principal no devolvió un pedido válido';
  if (!problem && extracted && !extracted.ok) {
    problem = extracted.error || 'La ventana operativa no contiene un pedido';
    if (transcript.audioProblem) problem = `${transcript.audioProblem}. ${problem}`;
    else ignored = true;
  }
  if (!problem && extracted?.ok && !['anexo', 'nuevo'].includes(extracted.action)) problem = 'El modelo no indicó si el pedido es nuevo o un anexo';
  const rawOrderText = String(extracted?.rawOrderText || '').trim();
  const numericValue = (value) => {
    const compact = String(value).replace(/\s/g, '');
    if (/^\d{1,3}(?:\.\d{3})+$/.test(compact)) return Number(compact.replace(/\./g, ''));
    if (/^\d{1,3}(?:,\d{3})+$/.test(compact)) return Number(compact.replace(/,/g, ''));
    return Number(compact.replace(',', '.'));
  };
  const items = rawOrderText.split(/\r?\n|;+/).map((line) => line.replace(/^\s*(?:[-*•]|\d+[.)])\s*/, '').trim()).filter(Boolean).slice(0, 100).map((rawLine) => {
    const rawText = rawLine.slice(0, 500);
    const byAmount = rawLine.match(/^(por\s+)?\$?\s*([\d.,]+)\s*(mil|k)?\s*(?:pesos?)?\s*(?:(?:de|en)\s+)?(.+)$/i);
    if (byAmount) {
      let amount = numericValue(byAmount[2]);
      if (byAmount[3] && amount < 1000) amount *= 1000;
      const monetary = Boolean(byAmount[3]) || amount >= 1000 || /^por\s+\$?/i.test(rawLine) || rawLine.startsWith('$');
      if (monetary) return { name: byAmount[4].trim().slice(0, 160), quantity: amount, unit: 'COP', quantityKind: 'amount', rawText };
    }
    return { name: rawLine.slice(0, 160), quantity: 1, rawText };
  });
  if (!problem && !rawOrderText) problem = 'La extracción no produjo el texto completo del pedido';
  if (!problem && !items.length) problem = 'El texto del pedido no contiene líneas utilizables';
  const orderAction = transcript.openOrder && extracted?.action === 'anexo' ? 'update' : 'new';
  const name = String(extracted?.customer?.name || input.contactName || '').trim();
  const phone = String(extracted?.customer?.phone || input.contactPhone || '').trim();
  const document = String(extracted?.customer?.document || input.contactDocument || '').trim();
  const address = String(extracted?.delivery?.address || input.contactAddress || '').trim();
  const neighborhood = String(extracted?.delivery?.neighborhood || input.contactNeighborhood || '').trim();
  const zone = String(extracted?.delivery?.zone || input.contactZone || '').trim();
  const pickup = /recog|tienda|pickup/.test(String(extracted?.delivery?.type || input.deliveryType || '').toLowerCase());
  const missing = [!name && 'nombre', !phone && 'teléfono', !address && !pickup && 'dirección', !neighborhood && !pickup && 'barrio'].filter(Boolean);
  const notes = [extracted?.notes, transcript.audioProblem ? `⚠️ ${transcript.audioProblem}` : null, missing.length ? `Datos pendientes: ${missing.join(', ')}` : null].map((value) => String(value || '').trim()).filter(Boolean).join(' · ');
  const delivery = pickup ? { type: 'recogida' } : { type: 'domicilio', ...(address ? { address } : {}) };
  const uniqueSeed = [transcript.idempotencySeed, rawOrderText, name, address, itemIndex].join('|');
  return { json: {
    valid: !problem, ignored, problem, conversationId, idempotencySeed: uniqueSeed, summaryText: visual.paymentProof === true ? transcript.transcript : rawOrderText,
    payload: { locationId: input.locationId, contactId: input.contactId, conversationId: conversationId || undefined,
      customer: { name: name || undefined, phone: phone || undefined, document: document || undefined, address: address || undefined, neighborhood: neighborhood || undefined, zone: zone || undefined },
      delivery, paymentMethod: extracted?.paymentMethod || undefined, items, rawOrderText, notes: notes || undefined,
      orderAction, contextUntil: transcript.contextUntil || undefined },
  }, pairedItem: { item: itemIndex } };
});

// Lee únicamente la ventana operativa vigente (2 p. m. a 1:59:59 p. m. de Bogotá) y lo posterior al cursor `since`.
const input = $('Normalizar entrada').first().json;
const response = $input.first().json;
const context = $('Contexto del pedido').first().json;
const contextStatus = Number(context.statusCode || 0);
const cutoffValue = context.body?.cutoff;
const windowStart = cutoffValue ? new Date(cutoffValue) : null;
const contextOk = contextStatus >= 200 && contextStatus < 300 && windowStart && !Number.isNaN(windowStart.getTime());
const openOrder = contextOk ? context.body?.openOrder || null : null;
const since = contextOk && context.body?.since ? new Date(context.body.since) : null;
const raw = response.body?.messages;
const messages = Array.isArray(raw) ? raw : Array.isArray(raw?.messages) ? raw.messages : [];
const timeZone = 'America/Bogota';
const dayKey = (date) => {
  const parts = new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(date);
  const values = Object.fromEntries(parts.filter((part) => part.type !== 'literal').map((part) => [part.type, part.value]));
  return `${values.year}-${values.month}-${values.day}`;
};
const parseDate = (value) => {
  if (value === undefined || value === null || value === '') return null;
  const numeric = Number(value);
  const date = Number.isFinite(numeric) ? new Date(numeric < 1e12 ? numeric * 1000 : numeric) : new Date(value);
  return Number.isNaN(date.getTime()) ? null : date;
};
const AUDIO_EXT = /\.(?:ogg|oga|opus|mp3|mpga|mpeg|m4a|wav|webm|aac|amr)(?:$|[?#])/i;
const IMAGE_EXT = /\.(?:jpe?g|png|gif|webp|heic)(?:$|[?#])/i;
const classify = (message) => {
  const urls = Array.isArray(message.attachments) ? message.attachments.filter((value) => typeof value === 'string') : [];
  const contentType = String(message.contentType || '').toLowerCase();
  const kind = String(message.messageType || message.type || '').toLowerCase();
  const audioMessage = contentType.startsWith('audio/') || /audio|voice|ptt/.test(kind);
  const imageMessage = contentType.startsWith('image/') || /image|photo/.test(kind);
  return urls.map((url) => ({ url, kind: audioMessage || AUDIO_EXT.test(url) ? 'audio' : imageMessage || IMAGE_EXT.test(url) ? 'image' : 'other' }));
};

const today = dayKey(new Date());
let current = messages
  .map((message) => ({ ...message, parsedDate: parseDate(message.dateAdded || message.createdAt || message.dateUpdated) }))
  .filter((message) => message.parsedDate && (!windowStart || message.parsedDate >= windowStart))
  .filter((message) => !since || message.parsedDate > since)
  .sort((a, b) => a.parsedDate - b.parsedDate);

// Defensa adicional: si no hay cursor ni pedido abierto, un marcador explícito de pedido nuevo
// descarta productos anteriores de la misma ventana antes de pedir la extracción al modelo.
if (!since && !openOrder) {
  const boundary = /\b(?:otro pedido|pedido aparte|nuevo pedido|pedido nuevo|por separado|para otra persona|para otra direcci[oó]n)\b/i;
  let boundaryIndex = -1;
  current.forEach((message, index) => {
    if (message.direction === 'inbound' && boundary.test(String(message.body || ''))) boundaryIndex = index;
  });
  if (boundaryIndex >= 0) current = current.slice(boundaryIndex);
}

const turns = [];
const images = [];
const audios = [];
for (const message of current) {
  const role = message.direction === 'inbound' ? 'CLIENTE' : 'FÉNIX J.A.';
  const inbound = message.direction === 'inbound';
  const body = typeof message.body === 'string' ? message.body.trim() : '';
  if (body) turns.push(`${role}: ${body}`);
  for (const attachment of classify(message)) {
    if (attachment.kind === 'image') {
      turns.push(`${role}: [IMAGEN ADJUNTA]`);
      if (inbound) images.push(attachment.url);
    } else if (attachment.kind === 'audio' && inbound) {
      const key = `AUDIO ${audios.length + 1}`;
      audios.push({ key, url: attachment.url, messageId: message.id || null });
      turns.push(`${role}: [${key}]`);
    } else if (attachment.kind === 'audio') {
      turns.push(`${role}: [NOTA DE VOZ DEL EQUIPO]`);
    } else {
      turns.push(`${role}: [ARCHIVO ADJUNTO]`);
    }
  }
}
const inboundMessages = current.filter((message) => message.direction === 'inbound');
const lastInbound = inboundMessages.at(-1);
const orderWindowStart = windowStart?.toISOString() || null;
return [{ json: {
  transcript: turns.join('\n'),
  turns: turns.length,
  messagesToday: current.length,
  imageUrls: [...new Set(images)].slice(-10),
  audios: audios.slice(-10),
  readStatus: response.statusCode,
  bogotaDay: today,
  inboundMessages: inboundMessages.length,
  contextOk: Boolean(contextOk),
  contextStatus,
  openOrder,
  orderWindowStart,
  contextUntil: current.at(-1)?.parsedDate?.toISOString() || null,
  idempotencySeed: `${input.contactId}|${orderWindowStart || today}|${lastInbound?.id || lastInbound?.parsedDate?.toISOString() || "sin-mensaje"}`,
} }];

// La tool de GHL solo ordena procesar; crear o actualizar lo decide la app.
const webhook = $('Webhook').first().json;
const body = webhook.body || {};
const rawCustom = body.customData || body.custom_data || {};
let custom = rawCustom;
if (typeof rawCustom === 'string') {
  try { custom = JSON.parse(rawCustom); } catch (error) { custom = {}; }
}
const clean = (value) => value === undefined || value === null ? '' : String(value).trim();
const pick = (...values) => values.map(clean).find(Boolean) || '';
const normalized = {};
for (const source of [body, custom]) {
  if (!source || typeof source !== 'object') continue;
  for (const [key, value] of Object.entries(source)) normalized[key.toLowerCase().replace(/[\s_]+/g, ' ').trim()] = value;
}
const field = (...names) => pick(...names.map((name) => normalized[name]));
return [{ json: {
  locationId: pick(body.locationId, custom.locationId, body.location?.id, body.location_id, custom.location_id),
  contactId: pick(body.contactId, custom.contactId, body.contact_id, body.contact?.id, custom.contact_id),
  contactName: pick(body.contactName, custom.contactName, body.full_name, custom.full_name, `${clean(body.first_name)} ${clean(body.last_name)}`),
  contactPhone: pick(body.contactPhone, custom.contactPhone, body.phone, custom.phone),
  contactDocument: pick(body.contactDocument, custom.contactDocument, field('nit o cédula', 'nit o cedula', 'documento de identidad', 'cedula', 'document')),
  contactAddress: pick(body.contactAddress, custom.contactAddress, field('agrega direccion de entrega', 'dirección completa', 'direccion de envio', 'address1'), body.full_address),
  contactNeighborhood: pick(body.contactNeighborhood, body.contactBarrio, custom.contactNeighborhood, custom.contactBarrio, field('barrio')),
  contactZone: pick(body.contactZone, body.contactZona, custom.contactZone, custom.contactZona, field('zona')),
  deliveryType: pick(body.deliveryType, body.delivery_type, custom.deliveryType, custom.delivery_type, field('¿es a domicilio o recoges en tienda? *', 'es a domicilio o recoges en tienda? *', 'es a domicilio o recoges en tienda', 'modalidad de entrega', 'entrega')),
  registrationComplete: pick(body.registrationComplete, custom.registrationComplete, field('registro minorista completo')),
} }];
